,["92420_SpearThurses"]={["bgDesc"]="發生畸變後的矛衛機體，擁有了極強的攻擊性，顏色也變成了怪異的黯黑色，擅于利用重矛向要害發起攻擊。",["type"]=1,["index"]=263,["name2"]="矛斗士",["id"]="92420_SpearThurses",["unlock_type"]=1,["bShowInAltas"]=true,["body"]=2,["skillDesc"]="畸變矛衛能使單體目標防禦下降。",["race"]=3,["key"]="92420_SpearThurses",["unlock_id"]={1712}
