,["9420_LycorisRadiata"]={["bgDesc"]="受到異變輻射波入侵後的赤夕，從失控暴走狀態脫離，但在異變影響下變得狂暴且渴望戰鬥，只記得自己要盡全力殲滅非本星系的外來者，戰力也得到了一定提升。",["type"]=8,["index"]=204,["name2"]="赤夕异变",["id"]="9420_LycorisRadiata",["unlock_type"]=1,["bShowInAltas"]=true,["body"]=2,["skillDesc"]="赤夕能夠為隊友提供各式各樣的增益以及耐久修復效果，還可以幫助隊友分攤傷害。",["race"]=2,["key"]="LycorisRadiata",["unlock_id"]={1418}
,["aModels"]=9420001,["name"]="赤夕「異變」",["name_en"]="FrenziedSpear",["aCards"]={94200}
}
,["9201_Fighter"]={["bgDesc"]="諾斯板塊製造的人形造物，擁有優異的作戰性能。此機作為護衛型機體，可以一邊保護友機一邊推進戰線。",["type"]=1,["index"]=64,["name2"]="盾斗士",["id"]="9201_Fighter",["unlock_type"]=1,["bShowInAltas"]=true,["body"]=2,["skillDesc"]="盾鬥士能對單體目標施加戰術嘲諷。",["race"]=3,["key"]="9201_Fighter",["unlock_id"]={1201}
