}
,["92400_SwordThurses"]={["bgDesc"]="發生畸變後的劍衛機體，擁有了極強的攻擊性，顏色也變成了怪異的黯黑色，攻擊力比之前增強許多。",["type"]=1,["index"]=268,["name2"]="盾斗士",["id"]="92400_SwordThurses",["unlock_type"]=1,["bShowInAltas"]=true,["body"]=2,["skillDesc"]="畸變劍衛揮動巨劍撕裂敵方目標，造成物理傷害，並對目標施加割裂效果。",["race"]=3,["key"]="92400_SwordThurses",["unlock_id"]={1713}
