,["9072_Hypnos01"]={["bgDesc"]="哈迪斯在暗面收服的神秘造物，內部搭載的智能模擬系統賦予了其高度自學能力和獨立思考能力。不但單體就擁有匹敵機神的性能，與『孿生機-塔納托斯』協同作戰時，戰鬥力更能得到飛躍性的提升。",["type"]=9,["index"]=48,["name2"]="修普诺斯",["id"]="9072_Hypnos01",["unlock_type"]=1,["bShowInAltas"]=true,["body"]=3,["skillDesc"]="藏身於虛空中的修普諾斯可奪去目標的意識，令其陷入無意識的“睡眠”",["race"]=3,["key"]="9072_Hypnos01",["unlock_id"]={1112}
